// Generated by scripts/build-exemplars.mjs — edit src/gallery/, not this file.

import { useMemo } from 'react';
import * as d3 from 'd3';

type Receipt = { country: string; before: number; after: number };

/** Government receipts as a percentage of GDP, 1970 vs 1979 (Tufte). */
const receipts: Receipt[] = [
  { country: 'Sweden', before: 46.9, after: 57.4 },
  { country: 'Netherlands', before: 44.0, after: 55.8 },
  { country: 'Norway', before: 43.5, after: 52.2 },
  { country: 'Britain', before: 40.7, after: 39.0 },
  { country: 'France', before: 39.0, after: 43.4 },
  { country: 'Germany', before: 37.5, after: 42.9 },
  { country: 'Belgium', before: 35.2, after: 43.2 },
  { country: 'Canada', before: 35.2, after: 35.8 },
  { country: 'Finland', before: 34.9, after: 38.2 },
  { country: 'Italy', before: 30.4, after: 35.7 },
  { country: 'United States', before: 30.3, after: 32.5 },
  { country: 'Greece', before: 26.8, after: 30.6 },
  { country: 'Switzerland', before: 26.5, after: 33.2 },
  { country: 'Spain', before: 22.5, after: 27.1 },
  { country: 'Japan', before: 20.7, after: 26.6 }
];

/** One row per label with its two readings, plus the headings those readings belong to. */
export type Data = {
  rows: { country: string; before: number; after: number }[];
  columns: [string, string];
};

const DEMO: Data = { rows: receipts, columns: ['1970', '1979'] };

const MARGIN = { top: 44, right: 148, bottom: 16, left: 148 };
const LABEL_GAP = 8;
const SEPARATION = 13;
const RISING = '#7fbf94';
const FALLING = '#d4715e';

const formatValue = d3.format('.1f');

/**
 * Iterative dodge: nudge overlapping label positions apart in place until every
 * neighbouring pair clears `separation`. Pure, so it can run inside useMemo.
 */
function dodge(positions: number[], separation = SEPARATION, maxIterations = 12): number[] {
  const spread = positions.slice();
  if (spread.length < 2) return spread;
  const order = d3.range(spread.length);
  for (let iteration = 0; iteration < maxIterations; iteration++) {
    order.sort((a, b) => d3.ascending(spread[a], spread[b]));
    let error = 0;
    for (let i = 1; i < spread.length; i++) {
      const gap = spread[order[i]] - spread[order[i - 1]];
      if (gap >= separation) continue;
      const shift = (separation - gap) / 2;
      error = Math.max(error, shift);
      spread[order[i - 1]] -= shift;
      spread[order[i]] += shift;
    }
    if (error < 0.1) break;
  }
  return spread;
}

export default function SlopeChart({ data = DEMO, width }: { data?: Data; width: number }) {
  const height = Math.round(width * 0.62);
  const innerWidth = width - MARGIN.left - MARGIN.right;
  const innerHeight = height - MARGIN.top - MARGIN.bottom;

  const x = useMemo(
    () => d3.scalePoint<number>().domain([0, 1]).range([0, innerWidth]),
    [innerWidth]
  );

  const y = useMemo(
    () =>
      d3
        .scaleLinear()
        .domain(
          d3.extent(data.rows.flatMap((d) => [d.before, d.after])) as [number, number]
        )
        .range([innerHeight, 0]),
    [data, innerHeight]
  );

  const series = useMemo(() => {
    const leftLabels = dodge(data.rows.map((d) => y(d.before)));
    const rightLabels = dodge(data.rows.map((d) => y(d.after)));
    return data.rows.map((d, i) => ({
      ...d,
      startY: y(d.before),
      endY: y(d.after),
      leftLabelY: leftLabels[i] ?? 0,
      rightLabelY: rightLabels[i] ?? 0,
      color: d.after >= d.before ? RISING : FALLING
    }));
  }, [data, y]);

  if (width === 0) return null;

  return (
    <svg
      viewBox={`0 0 ${width} ${height}`}
      width="100%"
      height={height}
      role="img"
      aria-label="Slope chart of government receipts as a percentage of GDP in 1970 and 1979 for fifteen countries"
    >
      <g transform={`translate(${MARGIN.left},${MARGIN.top})`}>
        <g className="axis" textAnchor="middle">
          {data.columns.map((label, i) => (
            <g key={label} transform={`translate(${x(i) ?? 0},0)`}>
              <text y={-22}>{label}</text>
              <line y1={-16} y2={-8} />
            </g>
          ))}
        </g>

        <g fill="none" strokeWidth={1.5}>
          {series.map((d) => (
            <line
              key={d.country}
              x1={x(0) ?? 0}
              y1={d.startY}
              x2={x(1) ?? 0}
              y2={d.endY}
              stroke={d.color}
              strokeOpacity={0.8}
            >
              <title>{`${d.country}: ${formatValue(d.before)} to ${formatValue(d.after)}`}</title>
            </line>
          ))}
        </g>

        <g fontSize={11}>
          {series.map((d) => (
            <text
              key={d.country}
              x={(x(0) ?? 0) - LABEL_GAP}
              y={d.leftLabelY}
              dy="0.35em"
              textAnchor="end"
              fill={d.color}
            >
              {`${d.country} ${formatValue(d.before)}`}
            </text>
          ))}
          {series.map((d) => (
            <text
              key={d.country}
              x={(x(1) ?? 0) + LABEL_GAP}
              y={d.rightLabelY}
              dy="0.35em"
              textAnchor="start"
              fill={d.color}
            >
              {`${formatValue(d.after)} ${d.country}`}
            </text>
          ))}
        </g>
      </g>
    </svg>
  );
}
